function usePanelDisclosure(id:string,defaultOpen=true){
 const key="damage-panel-"+id;
 const[open,setOpen]=useState(()=>{const saved=localStorage.getItem(key);return saved===null?defaultOpen:saved!=="collapsed"});
 const toggle=()=>setOpen(value=>{const next=!value;localStorage.setItem(key,next?"open":"collapsed");return next});
 return {open,toggle};
}
function PanelCollapseButton({open,toggle,label}:{open:boolean;toggle:()=>void;label:string}){
 return <button className="damage-inline-collapse" aria-expanded={open} aria-label={`${open?"Collapse":"Expand"} ${label}`} title={`${open?"Collapse":"Expand"} ${label}`} onClick={toggle}><i/></button>;
}

